// Fork of "colorful arcs" by franzbernhard. https://shadertoy.com/view/XXKfWm
// 2025-02-01 05:00:40

#define PI 3.14159265359
#define NUM_LIGHTS 7

//https://www.shadertoy.com/view/lscGDr
float gradientNoise(vec2 uv) {
    const vec3 magic = vec3(0.06711056, 0.00583715, 52.9829189);
    return fract(magic.z * fract(dot(uv, magic.xy)));
}

//https://www.shadertoy.com/view/ll2GD3
vec3 palette( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.28318*(c*t+d) );
}


float map(float value, float inMin, float inMax, float outMin, float outMax) {
    return outMin + (outMax - outMin) * (value - inMin) / (inMax - inMin);
}

mat2 rotate(float a) {
	return mat2(cos(a), -sin(a), sin(a), cos(a));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; 

    float time = iTime * 0.75;

    vec3 finalColor = vec3(0.0);
    float sumWeights = 0.0;

    vec3 bgColor = vec3(0.75);
    float bgWeight = 0.05;
	finalColor += bgColor * bgWeight;
	sumWeights += bgWeight;

    for (int i = 0; i < NUM_LIGHTS; i++) {
        float n = float(i) / float(NUM_LIGHTS);
		// float wave = sin(n * PI + time ) * 0.5 + smoothstep(0.0, 0.0, sin(time * 0.4)) * 5.0;
        float wave = sin(n * PI + time ) * 0.5 + (sin(time * 0.4) + 1.0) * 3.0;

        float distance = 0.3 + wave * 0.125;
        vec2 position = vec2(cos(n * PI * 2. + time * 0.1) * distance, sin(n * PI * 2. + time * 0.1) * distance);

        vec2 direction  = position;
        direction = rotate(1. + wave * 0.2) * direction;

        float arcAt = 0.5;
        vec2 toLight = position - uv;
        float distFragLight = length(toLight);
        distFragLight = mix(1000., distFragLight, step(arcAt, distFragLight));

        float lightConeAngle = 6.; 
        float lightDot = pow(clamp(dot(normalize(toLight), normalize(-direction)), 0.0, 1.0), lightConeAngle);

        float decayRate = 2.5;
        float distanceFactor = exp(-1.0 * decayRate * distFragLight);

        vec3 color = palette( wave, vec3(0.5,0.5,0.5),vec3(0.5,0.5,0.5),vec3(1.0,1.0,1.0),vec3(0.0,0.10,0.20) );
        color = clamp(color, 0., 1.);
        vec3 lightColor = color * lightDot * distanceFactor;

        finalColor += lightColor;
        sumWeights +=  distanceFactor * lightDot;
    }

    finalColor = finalColor / sumWeights;
    finalColor = pow(finalColor, vec3(1. / 2.2)); //gammma
    finalColor += (1.0/255.0) * gradientNoise(fragCoord) - (0.5/255.0); //banding

    fragColor = vec4(finalColor, 1.0);
}
